"use client";

import { Fragment, useEffect, useRef, useState } from "react";
import { useChat } from "@ai-sdk/react";
import {
  JSONUIProvider,
  Renderer,
  buildSpecFromParts,
  useJsonRenderMessage,
} from "@json-render/react";
import { motion } from "motion/react";
import { ChatDevtools } from "@/features/chat/components/chat-devtools";
import { ChatMessage } from "@/components/ui/chat-message";
import { InputMessage } from "@/components/ui/input-message";
import { ScrollArea } from "@/components/ui/scroll-area";
import { catalog } from "@/features/chat/chat-catalog";
import { ReplySteps } from "@/features/chat/components/reply-steps";
import { registry } from "@/features/chat/chat-registry";
import { useSize } from "@/lib/size-context";
import { spring } from "@/lib/springs";
import { cn } from "@/lib/utils";
import type { Chat as ChatInstance } from "@ai-sdk/react";
import type { UIMessage } from "ai";

const PINNED_PX = 48;

/**
The element that scrolls inside a Fluid ScrollArea: its ref points at the outer root, and the viewport inside it does the scrolling.
*/
function viewportOf(root: HTMLElement | null) {
  return (
    root?.querySelector<HTMLElement>('[data-slot="scroll-area-viewport"]') ??
    null
  );
}

const SUGGESTIONS = [
  "How's NVDA doing?",
  "Show me Apple over the past year",
  "How did Tesla do this week?",
];

export const Chat = ({
  chat,
  input = true,
  disabled = false,
  placeholder = "Ask about a stock…",
  className,
}: {
  /** An AI SDK chat instance to drive, e.g. one with a custom transport.
   *  Omitted, the chat posts to /api/chat. Give it a fixed id. */
  readonly chat?: ChatInstance<UIMessage>;
  /**
  Show the message composer.
  */
  readonly input?: boolean;
  /**
  Show the composer but don't accept messages (a read-only demo).
  */
  readonly disabled?: boolean;
  readonly placeholder?: string;
  readonly className?: string;
}) => {
  // A fixed id: the AI SDK would otherwise make a random one during render,
  // which a prerender (Cache Components) rejects.
  const { messages, sendMessage, status, stop, error } = useChat(
    chat ? { chat } : { id: "chat" }
  );
  const [draft, setDraft] = useState("");
  const { type } = useSize();

  const scrollReference = useRef<HTMLDivElement>(null);
  const contentReference = useRef<HTMLDivElement>(null);
  const pinnedReference = useRef(true);
  const bottomReference = useRef<HTMLDivElement>(null);
  // Follows the reply as it grows, unless the reader scrolled up to read:
  // the chat stays pinned while the marker at its end is within PINNED_PX of
  // the view. Resize observers run before intersection observers in a frame,
  // so growth scrolls first and the marker is still in view when it's checked.
  useEffect(() => {
    const element = viewportOf(scrollReference.current);
    const content = contentReference.current;
    const bottom = bottomReference.current;
    if (!(element && content && bottom)) {
      return;
    }
    const resize = new ResizeObserver(() => {
      if (pinnedReference.current) {
        element.scrollTo({ top: element.scrollHeight });
      }
    });
    const pin = new IntersectionObserver(
      ([entry]) => {
        pinnedReference.current = entry?.isIntersecting ?? true;
      },
      { root: element, rootMargin: `0px 0px ${PINNED_PX}px 0px` }
    );
    resize.observe(content);
    pin.observe(bottom);
    return () => {
      resize.disconnect();
      pin.disconnect();
    };
  }, []);
  useEffect(() => {
    pinnedReference.current = true;
    const element = viewportOf(scrollReference.current);
    element?.scrollTo({ top: element.scrollHeight });
  }, [messages.length]);

  const isBusy = status === "submitted" || status === "streaming";
  const turns = turnsOf(messages);
  const lastId = messages.at(-1)?.id;
  const lastReply = messages.findLast(
    (message) => message.role === "assistant"
  );

  return (
    <JSONUIProvider registry={registry}>
      <ChatDevtools
        spec={lastReply ? buildSpecFromParts(lastReply.parts) : null}
        catalog={catalog}
        messages={messages}
        position="right"
      />
      <div className={cn("flex min-h-0 flex-col", className)}>
        <ScrollArea ref={scrollReference} className="min-h-0 flex-1">
          <div ref={contentReference} className="flex flex-col gap-4 p-4">
            {turns.map((turn, index) => {
              const isLatest = index === turns.length - 1;
              return (
                <Fragment key={turn.id}>
                  {turn.question ? (
                    <ChatMessage from="user">
                      {textOf(turn.question)}
                    </ChatMessage>
                  ) : null}
                  {turn.reply || (isLatest && isBusy) ? (
                    <AssistantMessage
                      message={turn.reply}
                      streaming={
                        isBusy ? !turn.reply || turn.reply.id === lastId : false
                      }
                    />
                  ) : null}
                </Fragment>
              );
            })}
            {error ? (
              <p className={cn(type.caption, "text-muted-foreground")}>
                Something went wrong. Send the message again.
              </p>
            ) : null}
            <div ref={bottomReference} aria-hidden className="-mt-4 h-px" />
          </div>
        </ScrollArea>

        {input ? (
          <div className="p-3 pt-0">
            <InputMessage
              value={draft}
              onValueChange={setDraft}
              onSend={(text) => {
                if (!text) {
                  return;
                }

                sendMessage({ text });
                setDraft("");
              }}
              status={isBusy ? "streaming" : "idle"}
              onStop={stop}
              disabled={disabled}
              placeholder={placeholder}
              suggestions={
                messages.length === 0 && !disabled ? SUGGESTIONS : undefined
              }
            />
          </div>
        ) : null}
      </div>
    </JSONUIProvider>
  );
};

interface Turn {
  id: string;
  question?: UIMessage;
  reply?: UIMessage;
}

function turnsOf(messages: readonly UIMessage[]): Turn[] {
  const turns: Turn[] = [];
  for (const message of messages) {
    const last = turns.at(-1);
    if (message.role === "user") {
      turns.push({ id: message.id, question: message });
    } else if (last && !last.reply) {
      last.reply = message;
    } else {
      turns.push({ id: message.id, reply: message });
    }
  }
  return turns;
}

const NO_PARTS: UIMessage["parts"] = [];

const AssistantMessage = ({
  message,
  streaming,
}: {
  readonly message?: UIMessage;
  readonly streaming: boolean;
}) => {
  const { spec, text } = useJsonRenderMessage(message?.parts ?? NO_PARTS);
  const [isAnswerShown, setIsAnswerShown] = useState(false);
  return (
    <div className="flex flex-col gap-3">
      <ReplySteps
        spec={spec}
        hasText={text.length > 0}
        streaming={streaming}
        onFinish={() => setIsAnswerShown(true)}
      />
      {isAnswerShown ? (
        <motion.div
          className="flex flex-col gap-3"
          initial={{ opacity: 0, y: 6 }}
          animate={{ opacity: 1, y: 0 }}
          transition={spring.slow}
        >
          {text ? <ChatMessage from="assistant">{text}</ChatMessage> : null}
          {spec ? (
            <Renderer spec={spec} registry={registry} loading={streaming} />
          ) : null}
        </motion.div>
      ) : null}
    </div>
  );
};

function textOf(message: UIMessage) {
  return message.parts
    .map((part) => (part.type === "text" ? part.text : ""))
    .join("");
}

import { z } from "zod";
import { cn } from "@/lib/utils";
import type { ReactNode } from "react";

export const CardGroup = ({
  children,
  className,
}: {
  readonly children?: ReactNode;
  readonly className?: string;
}) => (
  <div className={cn("@container w-full", className)}>
    <div className="grid grid-cols-1 items-start gap-3 @2xl:grid-cols-2">
      {children}
    </div>
  </div>
);

export const cardGroupCatalogEntry = {
  description:
    "Holds several cards in one reply. Use it as the root whenever the reply shows more than one card, with one card per child.",
  props: z.object({}),
  slots: ["default"],
};

"use client";

import dynamic from "next/dynamic";

// json-render's devtools panel, in development only. Behind a dynamic import
// on NODE_ENV, so production builds don't ship its code at all (on its own
// it renders null in production but still lands in the bundle).
export const ChatDevtools =
  process.env.NODE_ENV === "development"
    ? dynamic(
        () =>
          import("@json-render/devtools-react").then(
            (module) => module.JsonRenderDevtools
          ),
        { ssr: false }
      )
    : () => null;

"use client";

import { useEffect, useRef, useState } from "react";
import {
  ThinkingStep,
  ThinkingStepSource,
  ThinkingStepSources,
  ThinkingSteps,
  ThinkingStepsContent,
  ThinkingStepsHeader,
} from "@/components/ui/thinking-steps";
import { lookups } from "@/features/chat/chat-steps";
import { listOf } from "@/features/chat/lookup";
import { spring } from "@/lib/springs";
import type { CardLookup, Source } from "@/features/chat/lookup";
import type { Spec } from "@json-render/core";
import type { IconName } from "@/lib/icon-context";
import type { ReactNode } from "react";

const DONE_HOLD_MS = 600;

const FOLD_MS = Math.round(spring.moderate.duration * 1000);

type Load =
  | { status: "loading" }
  | { status: "ready" }
  | { status: "error"; message: string };

interface Card {
  key: string;
  type: string;
  subject: string;
  lookup: CardLookup;
  props: Record<string, unknown>;
}

type StepStatus = "complete" | "active" | "pending";

interface Step {
  key: string;
  icon: IconName;
  label: string;
  description?: string;
  done: boolean;
  children?: ReactNode;
}

function cardsIn(spec: Spec | null): Card[] {
  const cards: Card[] = [];
  for (const element of Object.values(spec?.elements ?? {})) {
    const lookup = lookups[element.type];
    const properties = (element.props ?? {}) as Record<string, unknown>;
    const subject = lookup?.subject(properties);
    if (lookup && subject) {
      cards.push({
        key: `${element.type}:${subject}`,
        lookup,
        props: properties,
        subject,
        type: element.type,
      });
    }
  }
  return cards;
}

function hasSameKeys(left: readonly Card[], right: readonly Card[]): boolean {
  if (left.length !== right.length) {
    return false;
  }
  for (const [index, element] of left.entries()) {
    if (element?.key !== right[index]?.key) {
      return false;
    }
  }
  return true;
}

interface LoadPlan {
  readonly isReady: boolean;
  readonly cards: readonly Card[];
}

function useLoadPlan(cards: readonly Card[], isReady: boolean): LoadPlan {
  const [plan, setPlan] = useState<LoadPlan>({ cards, isReady });
  if (plan.isReady === isReady && hasSameKeys(plan.cards, cards)) {
    return plan;
  }
  const next = { cards, isReady };
  setPlan(next);
  return next;
}

function useLoads(cards: readonly Card[], ready: boolean) {
  const [loads, setLoads] = useState<Record<string, Load>>({});
  const plan = useLoadPlan(cards, ready);

  useEffect(() => {
    if (!plan.isReady) {
      return;
    }
    let isCancelled = false;
    for (const card of plan.cards) {
      const settle = (load: Load) => {
        if (!isCancelled) {
          setLoads((current) => ({ ...current, [card.key]: load }));
        }
      };
      card.lookup
        .load(card.props)
        .catch((error: unknown) =>
          settle({
            message: Error.isError(error) ? error.message : "It failed.",
            status: "error",
          })
        )
        .then(() => settle({ status: "ready" }));
    }
    return () => {
      isCancelled = true;
    };
  }, [plan]);

  return loads;
}

function useElapsed(isDone: boolean) {
  const [startedAt] = useState(() => performance.now());
  const [seconds, setSeconds] = useState<number | null>(null);
  useEffect(() => {
    if (isDone) {
      setSeconds((performance.now() - startedAt) / 1000);
    }
  }, [isDone, startedAt]);
  return seconds;
}

function SourceLink({ source }: { readonly source: Source }) {
  return (
    <a
      href={source.href}
      target="_blank"
      rel="noopener noreferrer"
      aria-label={`${source.label} (opens in a new tab)`}
      className="outline-none after:absolute after:inset-0 after:rounded-[inherit] after:content-[''] hover:underline hover:underline-offset-2 focus-visible:after:ring-1 focus-visible:after:ring-[color:var(--focus-ring,#6B97FF)]"
    >
      {source.label}
    </a>
  );
}

function intentOf(cards: readonly Card[]) {
  const byKind = new Map<CardLookup, string[]>();
  for (const card of cards) {
    byKind.set(card.lookup, [...(byKind.get(card.lookup) ?? []), card.subject]);
  }
  return [...byKind]
    .map(([lookup, subjects]) => lookup.intent(subjects))
    .join("; ");
}

export function ReplySteps({
  spec,
  hasText,
  streaming,
  onFinish,
}: {
  readonly spec: Spec | null;
  readonly hasText: boolean;
  /**
  The model is still writing this reply.
  */
  readonly streaming: boolean;
  /**
  The steps are done and folded: time to show the answer.
  */
  readonly onFinish: () => void;
}) {
  const cards = cardsIn(spec);
  const loads = useLoads(cards, !streaming);
  const [open, setOpen] = useState(true);

  const isStarted = hasText || spec !== null;
  const isWritten = isStarted && !streaming;
  const isFetched = cards.every((card) => {
    const load = loads[card.key];
    return load && load.status !== "loading";
  });
  const isDone = isWritten && isFetched;
  const seconds = useElapsed(isDone);

  const [isFolded, setIsFolded] = useState(false);
  const onFinishReference = useRef(onFinish);
  onFinishReference.current = onFinish;
  useEffect(() => {
    if (!isDone) {
      return;
    }
    const fold = setTimeout(() => {
      setIsFolded(true);
      setOpen(false);
    }, DONE_HOLD_MS);
    const finish = setTimeout(
      () => onFinishReference.current(),
      DONE_HOLD_MS + FOLD_MS
    );
    return () => {
      clearTimeout(fold);
      clearTimeout(finish);
    };
  }, [isDone]);

  const failures = cards.flatMap((card) => {
    const load = loads[card.key];
    return load?.status === "error" ? [`${card.subject}: ${load.message}`] : [];
  });
  const sources = [
    ...new Map(
      cards
        .flatMap((card) => card.lookup.sources(card.props))
        .map((source) => [source.href, source])
    ).values(),
  ];

  const steps: Step[] = [
    {
      description: isWritten && cards.length > 0 ? intentOf(cards) : undefined,
      done: spec ? isWritten : isStarted,
      icon: "message-circle",
      key: "understand",
      label: "Understanding the question",
    },
  ];
  if (isStarted && !spec) {
    steps.push({
      done: isWritten,
      icon: "pencil",
      key: "write",
      label: "Writing an answer",
    });
  }
  if (cards.length > 0) {
    steps.push({
      children: (
        <ThinkingStepSources>
          {sources.map((source, index) => (
            <ThinkingStepSource
              key={source.href}
              delay={0.05 * (index + 1)}
              className="relative"
            >
              <SourceLink source={source} />
            </ThinkingStepSource>
          ))}
        </ThinkingStepSources>
      ),
      description: failures.length > 0 ? failures.join(" ") : undefined,
      done: isFetched,
      icon: "search",
      key: "lookup",
      label: `Looking up ${listOf(cards.map((card) => card.subject))}`,
    });
  }
  steps.push({
    description:
      seconds === null ? undefined : `Took ${seconds.toFixed(1)} seconds.`,
    done: isDone,
    icon: "check",
    key: "done",
    label: "Done",
  });

  const active = steps.findIndex((step) => !step.done);
  const lastShown = active === -1 ? steps.length - 1 : active;
  const statusAt = (index: number): StepStatus => {
    if (active === -1 || index < active) {
      return "complete";
    }
    return index === active ? "active" : "pending";
  };

  const header =
    isFolded && seconds !== null
      ? `Worked for ${seconds.toFixed(1)}s`
      : "Thinking";

  return (
    <ThinkingSteps open={open} onOpenChange={setOpen}>
      <ThinkingStepsHeader>{header}</ThinkingStepsHeader>
      <ThinkingStepsContent>
        {steps.map((step, index) => {
          const status = statusAt(index);
          return (
            <ThinkingStep
              key={step.key}
              icon={step.icon}
              label={step.label}
              description={step.description}
              status={status}
              isLast={index === lastShown}
            >
              {status === "complete" ? step.children : undefined}
            </ThinkingStep>
          );
        })}
      </ThinkingStepsContent>
    </ThinkingSteps>
  );
}

/**
Where a card's data comes from: a source badge that links there.
*/
export interface Source {
  /**
  What the badge says, e.g. "finance.yahoo.com/quote/NVDA".
  */
  label: string;
  href: string;
}

export interface CardLookup {
  /**
  What the question asked for, given the cards' subjects: the description under "Understanding the question", e.g. "A stock quote for NVDA" or "The weather in London and Paris".
  */
  intent: (subjects: readonly string[]) => string;
  /**
  What one card is about, e.g. "London" or "NVDA"; null while the props aren't usable yet.
  */
  subject: (properties: Record<string, unknown>) => string | null;
  /** The card's own request for these props (shared, so the card reuses it
   *  when it mounts instead of fetching again). */
  load: (properties: Record<string, unknown>) => Promise<unknown>;
  /** Where this card's data comes from, shown as linked source badges.
   *  Badges with the same link appear once per reply. */
  sources: (properties: Record<string, unknown>) => readonly Source[];
}

/**
"London", "London and Paris", "London, Paris and Tokyo".
*/
export function listOf(items: readonly string[]) {
  return items.length <= 1
    ? (items[0] ?? "")
    : `${items.slice(0, -1).join(", ")} and ${items.at(-1)}`;
}

import { defineCatalog } from "@json-render/core";
import { schema } from "@json-render/react/schema";
import { cardGroupCatalogEntry } from "@/features/chat/components/card-group";

// Everything the model may put in a chat reply. The server turns this into
// the model's instructions (catalog.prompt); the client renders it through
// features/chat/chat-registry.tsx. CardGroup is the chat's own, for replies
// with several cards. Each genuicn card you install adds one line here and
// one there, next to it. For example, the quote card:
//
//   import { quoteCatalogEntry } from "@/features/quote/quote-catalog";
//   QuoteCard: quoteCatalogEntry,
export const catalog = defineCatalog(schema, {
  actions: {},
  components: {
    CardGroup: cardGroupCatalogEntry,
  },
});

"use client";

import { defineRegistry } from "@json-render/react";
import { catalog } from "@/features/chat/chat-catalog";
import { CardGroup } from "@/features/chat/components/card-group";

// How each catalog component renders in the chat. Each genuicn card you install adds one line here, next to CardGroup. For example, the quote card:
//
//   import { LiveQuoteCard } from "@/features/quote/components/live-quote-card";
//   QuoteCard: ({ props, loading }) => (
//     <LiveQuoteCard ticker={props.ticker} range={props.range ?? "1d"} streaming={loading} />
//   ),
export const { registry } = defineRegistry(catalog, {
  components: {
    CardGroup: ({ children }) => <CardGroup>{children}</CardGroup>,
  },
});

import type { CardLookup } from "@/features/chat/lookup";

// What the reply's thinking steps say about each card: where its data comes
// from, and what it read once the data arrived. The steps start (or reuse)
// the card's own request, so they track the real fetch and never add one.
// Each genuicn card you install adds one line here, next to its lines in chat-catalog.ts and chat-registry.tsx. For example, the quote card:
//
//   import { quoteLookup } from "@/features/quote/quote-steps";
//   QuoteCard: quoteLookup,
export const lookups: Record<string, CardLookup> = {};

import { pipeJsonRender } from "@json-render/core";
import {
  convertToModelMessages,
  createUIMessageStream,
  createUIMessageStreamResponse,
  streamText,
  toUIMessageStream,
} from "ai";
import { catalog } from "@/features/chat/chat-catalog";
import type { UIMessage, UIMessageChunk } from "ai";

export const maxDuration = 30;

const DEFAULT_MODEL = "anthropic/claude-haiku-4.5";

const instructions = catalog.prompt({
  customRules: [
    'When a card fits, your entire reply is the JSONL lines: no sentence before or after them (not even "I\'ll show you…") and no code fences. The chat shows the user its progress itself; the cards are the answer.',
    "When no component fits the user's message (a greeting, a question no card covers), reply with one or two short plain-text sentences instead of JSONL.",
    "Cards fetch their own live data. Never state prices, scores, temperatures or other figures a card shows; anything you write could be out of date.",
    "Show cards only for what the user's latest message asks about. Cards from earlier replies stay visible above, so never repeat them.",
    "A reply has exactly one root element. For one card, the card is the root. For several cards (several stocks in one question), the root is a CardGroup with one card per child; never leave a card outside the root.",
  ],
  mode: "standalone",
});

export async function POST(request: Request) {
  const { messages }: { messages: UIMessage[] } = await request.json();
  const now = new Date();
  const today = now.toISOString().slice(0, 10);

  const result = streamText({
    instructions: `${instructions}\n\nToday is ${today} (UTC). Work out relative dates such as "tomorrow" from it.`,
    messages: await convertToModelMessages(messages, {
      convertDataPart: (part) =>
        part.type === "data-spec"
          ? { text: `${JSON.stringify(specPatch(part.data))}\n`, type: "text" }
          : undefined,
    }),
    model: process.env.AI_GATEWAY_MODEL || DEFAULT_MODEL,
  });

  return createUIMessageStreamResponse({
    stream: createUIMessageStream({
      execute: ({ writer }) => {
        writer.merge(
          pipeJsonRender(
            toUIMessageStream({ stream: result.stream }).pipeThrough(
              stripFencesAndLeadingBlankLines()
            )
          )
        );
      },
    }),
  });
}

function specPatch(data: unknown) {
  return typeof data === "object" && data !== null && "patch" in data
    ? data.patch
    : data;
}

const FENCE_LINE = /^\s*```[\w-]*\s*$/;

function stripFencesAndLeadingBlankLines() {
  let line = "";
  let id = "";
  let hasContent = false;
  const emit = (
    controller: TransformStreamDefaultController<UIMessageChunk>
  ) => {
    const isNoise = FENCE_LINE.test(line) || (!hasContent && !line.trim());
    if (line && !isNoise) {
      hasContent = true;
      controller.enqueue({ delta: line, id, type: "text-delta" });
    }
    line = "";
  };
  return new TransformStream<UIMessageChunk, UIMessageChunk>({
    flush: emit,
    transform(chunk, controller) {
      if (chunk.type === "text-delta") {
        ({ id } = chunk);
        for (const character of chunk.delta) {
          line += character;
          if (character === "\n") {
            emit(controller);
          }
        }
        return;
      }
      if (chunk.type === "text-end") {
        emit(controller);
      }
      controller.enqueue(chunk);
    },
  });
}

import { Chat } from "@/features/chat/components/chat";

export default function ChatPage() {
  return (
    <main className="mx-auto flex h-svh w-full max-w-2xl flex-col">
      <Chat className="flex-1" />
    </main>
  );
}
